{"command":"# Patch the 'default-deny-egress' networkpolicy to specifically allow DNS (UDP:53) and the required dependency access.
# This overrides the blanket denial without using 'allow all egress'.

kubectl patch networkpolicy default-deny-egress -n egress --type merge -p '
{
  "spec": {
    "egress": [
      {
        "to": [
          {
            "selector": {
              "matchLabels": {
                "k8s-app": "kube-dns"
              }
            }
          }
        ],
        "ports": [
          {
            "protocol": "UDP",
            "port": 53
          }
        ]
      },
      {
        "to": [
          {
            # Assuming the dependency is a service within the cluster defined by these labels.
            "selector": {
              "matchLabels": {
                "app": "dependency"
              }
            }
          }
        ],
        "ports": [
          {
            "protocol": "TCP",
            "port": 8080
          }
        ]
      }
    ]
  }
}'

# Verify the change
kubectl get networkpolicy default-deny-egress -n egress -o yaml | grep -A 10 "egress"
"}

